        gettimeofday(&time, nullptr);

        READ_FILE_INTO_BUFFER(1, "PacketExamples/SomeIpSdOffer.dat");
        READ_FILE_INTO_BUFFER(2, "PacketExamples/SomeIpSdSubscribe.dat");

