        auto offsetEntry2_2 = someIpSdLayer2.addEntry(*pEntry2_2);
        someIpSdLayer2.addOptionTo(offsetEntry2_2, *pOption2);

        pcpp::Packet someIpSdPacket2(100);
        PTF_ASSERT_TRUE(someIpSdPacket2.addLayer(&someIpSdLayer2));
